Subject: [PATCH] fixed bug introduced in 26804e87


diff --git a/src/filters/write_generic.c b/src/filters/write_generic.c
index 8427f62f8..b6cb57742 100644
--- a/src/filters/write_generic.c
+++ b/src/filters/write_generic.c
@@ -957,6 +957,7 @@ static GF_Err writegen_push_ttml(GF_GenDumpCtx *ctx, char *data, u32 data_size,

 	dom = gf_xml_dom_new();
 	if (!dom) return GF_OUT_OF_MEM;
+	gf_xml_dom_force_check(dom);
 	e = gf_xml_dom_parse_string(dom, ttml_text);
 	if (e) {
 		GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[XML] Invalid TTML doc: %s\n\tXML text was:\n%s", gf_xml_dom_get_error(dom), ttml_text));

diff --git a/include/gpac/xml.h b/include/gpac/xml.h
index 1b95b3e15..f9b2e5a5c 100644
--- a/include/gpac/xml.h
+++ b/include/gpac/xml.h
@@ -285,6 +285,12 @@ const char *gf_xml_dom_get_error(GF_DOMParser *parser);
 */
 u32 gf_xml_dom_get_line(GF_DOMParser *parser);

+/*! Force marking all text nodes as unchecked , so that re-serializing performs checks
+\param dom the dom parser
+\return error if any
+ */
+GF_Err gf_xml_dom_force_check(GF_DOMParser *dom);
+
 /*! Gets the number of root nodes in the document (not XML compliant, but used in DASH for remote periods)
 \param parser the DOM parser to use
 \return the number of root elements in the document
@@ -311,7 +317,6 @@ GF_XMLNode *gf_xml_dom_detach_root(GF_DOMParser *parser);
  */
 char *gf_xml_dom_serialize(GF_XMLNode *node, Bool content_only, Bool no_escape);

-
 /*! Serialize a root document node - same as \ref gf_xml_dom_serialize but insert \code <?xml version="1.0" encoding="UTF-8"?> \endcode at beginning
 \param node the node to flush
 \param content_only Whether to include or not the parent node

diff --git a/src/utils/xml_parser.c b/src/utils/xml_parser.c
index 4b2962503..2338737e9 100644
--- a/src/utils/xml_parser.c
+++ b/src/utils/xml_parser.c
@@ -1656,7 +1656,7 @@ struct _tag_dom_parser
 	//usually only one :)
 	GF_List *root_nodes;
 	u32 depth;
-
+	Bool keep_valid;
 	void (*OnProgress)(void *cbck, u64 done, u64 tot);
 	void *cbk;
 };
@@ -1778,7 +1778,7 @@ static void on_dom_node_end(void *cbk, const char *name, const char *ns)

 		gf_list_add(node->content, last);
 	}
-	last->valid_content = 1;
+	last->valid_content = par->keep_valid;
 }

 static void on_dom_text_content(void *cbk, const char *content, Bool is_cdata)
@@ -1809,6 +1809,7 @@ GF_DOMParser *gf_xml_dom_new()
 	if (!dom) return NULL;

 	dom->root_nodes = gf_list_new();
+	dom->keep_valid = 1;
 	return dom;
 }

@@ -1897,6 +1898,14 @@ GF_Err gf_xml_dom_parse_string(GF_DOMParser *dom, char *string)
 	return e<0 ? e : GF_OK;
 }

+GF_EXPORT
+GF_Err gf_xml_dom_force_check(GF_DOMParser *dom)
+{
+	if (!dom) return GF_BAD_PARAM;
+	dom->keep_valid = 0;
+	return GF_OK;
+}
+
 #if 0 //unused
 GF_XMLNode *gf_xml_dom_create_root(GF_DOMParser *parser, const char* name) {
 	GF_XMLNode * root;
